import {store,pocket,url,asset,params,mountPage,esc,watchReads} from '../arg-ui.js?v=41';
import {CLIPS,SPRING_BV,AUTUMN_BV} from '../arg-content.js?v=40';
import {createMockPlayer,danmakuAt,displayTime} from './mock-player.js?v=40';
const app=document.querySelector('#app');let controller=null,lastFrame=-1,lastTime=0;
function render(){controller?.dispose();const p=params(),id=p.get('bv'),query=p.get('q')||'';if(!id){const results=Object.values(CLIPS).filter(v=>query&&[v.id,v.title,v.up].some(x=>x.toLowerCase().includes(query.toLowerCase())));app.innerHTML=`<div class="video-site"><header class="video-top"><a class="video-brand" href="index.html">▣ 哔哩哔哩 <small>青禾校园镜像</small></a><form method="get" action="index.html"><input name="q" value="${esc(query)}" placeholder="视频标题、UP主或BV号" aria-label="镜像搜索"><button>搜索</button></form></header><div class="arg-video-results"><h1>校园影像存档</h1>${results.map(v=>`<a href="index.html?bv=${v.id}"><img src="frames/${v.prefix}-01.svg" alt="视频封面"><h2>${esc(v.title)}</h2><small>${v.date} · ${v.id}</small></a>`).join('')||'<p>从原帖记下视频编号，可以在这里查询。上传时间和现场拍摄时间分别保留。</p>'}</div></div>`;return;}
 const v=CLIPS[id];if(!v){app.innerHTML='<h1>没有对应缓存</h1><a href="index.html">返回镜像检索</a>';return;}lastFrame=-1;app.innerHTML=`<section class="video-site"><header class="video-top"><a class="video-brand" href="index.html">▣ 哔哩哔哩 <small>青禾校园镜像</small></a><form action="index.html"><input name="q" placeholder="搜索视频或BV号"><button>搜索</button></form></header><div class="video-watch"><article><h1>${esc(v.title)}</h1><p class="video-meta">1.2万播放　${v.danmaku.length}条弹幕　上传 ${v.date}　${v.id}</p><div class="mock-video" data-playing="false"><div class="mock-screen">${[1,2,3,4].map((n,i)=>`<img class="mock-frame ${i===0?'active':''}" src="frames/${v.prefix}-0${n}.svg" alt="关键帧${n}：${id===SPRING_BV?['春季活动拍摄日期','跑道与器材入口','学生会搬运打印机','设备离场'][i]:['拍摄日期','接力赛','B机场记','离场'][i]}">`).join('')}<div class="mock-danmaku" aria-hidden="true"></div><span class="mock-dv" data-dv></span><p class="mock-caption" data-caption></p><button class="mock-frame-evidence" type="button" hidden></button></div><div class="player-controls"><button type="button" data-play aria-label="播放">▶</button><input type="range" min="0" max="${v.duration}" step="1" value="0" aria-label="播放进度"><span data-clock>00:00 / ${displayTime(v.duration)}</span><label><input type="checkbox" data-danmaku checked>弹幕</label></div></div><article class="video-description"><p>${esc(v.description)}</p><p>源素材：<a href="${url('pan',{folder:v.share})}">青禾班级网盘 / ${v.share}</a>。完整拍摄记录以原作者场记为准。</p></article><section class="mirror-comments"><h2>评论 / 最热</h2><article class="mirror-comment pinned"><b>置顶 · ${v.up}</b><p>四张关键帧：${[0,28,84,112].map(t=>`<a href="#t=${t}" data-seek="${t}">${displayTime(t)}</a>`).join('　')}。点击时间直接定位，原帧在网盘。${id===SPRING_BV?'学生会器材处的交接登记也放一起，缩写牌就在画面里。':'底片登记按拍摄日找，不按上传日找。'}</p></article><article class="mirror-comment"><b>隔壁班的</b><p>${id===SPRING_BV?'84秒后面那个人真是陈叙？别光看弹幕吧，学生会应该有设备签收。':'B机是哪天用的，照片袋上倒是有日期。'}</p></article><article class="mirror-comment"><b>青禾摄影社</b><p>远景不能凭长相认人。原作者提供的交接簿和场记确认在源素材夹里；用到片段请保留现场日期。</p></article></section><p>来源讨论：<a href="${url('forum',{thread:id===SPRING_BV?'reports':'sports'})}">返回原帖上下文</a></p></article><aside class="video-up"><div class="up-profile"><span class="up-avatar">摄</span><div><h2>${v.up}</h2><p>青禾高中学生社团</p></div></div><p>四帧缓存 / ${displayTime(v.duration)}</p><p>简介与场记需要交叉核对。</p></aside></div></section>`;
 const screen=app.querySelector('.mock-screen'),range=app.querySelector('input[type=range]'),button=app.querySelector('[data-play]'),dm=app.querySelector('.mock-danmaku'),capture=app.querySelector('.mock-frame-evidence');let showDanmaku=true;
 controller=createMockPlayer({duration:v.duration,starts:v.frames,onPause:t=>{store.dispatch('mark',{table:'clip-'+v.prefix,rows:[String(t)]});},onTime:(time,playing,index)=>{lastTime=time;app.querySelector('.mock-video').dataset.playing=String(playing);button.textContent=playing?'❚❚':'▶';button.setAttribute('aria-label',playing?'暂停':'播放');range.value=time;app.querySelector('[data-clock]').textContent=`${displayTime(time)} / ${displayTime(v.duration)}`;app.querySelector('[data-dv]').textContent=(id===SPRING_BV?'2025.03.14 14:':'2024.10.18 14:')+displayTime((id===SPRING_BV?25:5)*60+[0,28,84,112][index]);dm.innerHTML=showDanmaku?danmakuAt(v.danmaku,time).map((d,i)=>`<span style="top:${18+i*20}%;left:${100-(time-d.at)*22}%">${esc(d.text)}</span>`).join(''):'';
  app.querySelector('[data-caption]').textContent=index===2?(id===SPRING_BV?'场外声：陈叙，打印机往学生会器材处搬。XSH这块牌别挡着。':'场外声：正式比赛用B机，试拍另外存。'):index===0?(id===SPRING_BV?'2025年3月14日 · 春季接力展示':'2024年10月18日 · 秋季运动会'):'';
  if(index!==lastFrame){lastFrame=index;app.querySelectorAll('.mock-frame').forEach((img,i)=>img.classList.toggle('active',i===index));capture.hidden=index!==2;app.querySelectorAll('.mock-frame').forEach(img=>delete img.dataset.evidence);if(index===2){app.querySelectorAll('.mock-frame')[index].dataset.evidence=v.capture;capture.textContent='核对这一帧的时间与场记';}watchReads();}
 }});
 capture.onclick=()=>{const image=app.querySelector('.mock-frame.active');if(lastFrame===2&&image.complete&&image.naturalWidth>0)pocket.feedback(store.dispatch('collect',{id:v.capture}).message);};button.onclick=()=>controller.play();range.oninput=()=>controller.seek(range.value);app.querySelector('[data-danmaku]').onchange=e=>{showDanmaku=e.target.checked;controller.seek(controller.getTime());};app.querySelectorAll('[data-seek]').forEach(a=>a.onclick=e=>{e.preventDefault();controller.pause();controller.seek(Number(a.dataset.seek));});controller.seek(Number(p.get('t')||store.get().marks['clip-'+v.prefix]?.value?.[0]||0));
}
mountPage(render);document.addEventListener('visibilitychange',()=>{if(document.visibilityState!=='visible')controller?.pause();});window.addEventListener('blur',()=>controller?.pause());window.addEventListener('pagehide',()=>controller?.dispose());
